"""Build the procedural part of Prototype/ThirdParty/JewelryModels.  python3 -P build.py OUT_DIR
Writes OBJ + MTL per model, generated textures, and build_manifest.json (tris, bounds, offsets)."""
import sys, os, json
import numpy as np
from meshlib import write_obj, ground, bbox, RY, RX, RZ
from materials import MATS, mtl
import rings as R, items as I, gems as G, necks as N, textures as T
from rings import MM

OUT = sys.argv[1]; os.makedirs(OUT, exist_ok=True)
HEADER = ('JewelryModels pack - original procedural model, project-owned (generated by Source~/build.py).\n'
          'Units: metres. Y up. Front: +Z. Pivot: bottom centre unless README says otherwise.')

# ---------------------------------------------------------------- textures
TEX = {}
def tex(key, fn, *names):
    paths = [os.path.join(OUT, n) for n in names]
    fn(*paths); TEX[key] = names[0]
tex('WatchDial', T.watch_dial, 'WatchDial_Color.png')
tex('PriceTag', T.price_tags, 'PriceTags_Color.png')
tex('GoldBar1kg', lambda a, b: T.gold_bar(a, b, 'cast'), 'GoldBar1kg_Color.png', 'GoldBar1kg_Normal.png')
tex('GoldBar100g', lambda a, b: T.gold_bar(a, b, 'minted'), 'GoldBar100g_Color.png', 'GoldBar100g_Normal.png')
tex('GoldCoin', T.coin, 'GoldCoin_Color.png', 'GoldCoin_Normal.png')
tex('GiftBag', T.gift_bag, 'GiftBag_Color.png')
tex('TerminalTop', T.terminal_top, 'PaymentTerminal_Color.png')
tex('PosScreen', T.pos_screen, 'PosTablet_Screen.png')
tex('GemPaper', T.gem_paper, 'GemPaper_Color.png')

TEXMAT = {  # textured materials: base settings
    'WatchDial': dict(Kd=(1, 1, 1), metallic=0.3, smoothness=0.75, note='sunburst dial; texture WatchDial_Color.png'),
    'PriceTag': dict(Kd=(1, 1, 1), metallic=0.0, smoothness=0.2, note='price tag print atlas (4 x 2 cells)'),
    'GoldBar1kg': dict(Kd=(1, 1, 1), metallic=1.0, smoothness=0.78, note='cast bar; add GoldBar1kg_Normal.png as normal map (strength 1)'),
    'GoldBar100g': dict(Kd=(1, 1, 1), metallic=1.0, smoothness=0.9, note='minted bar; add GoldBar100g_Normal.png'),
    'GoldCoin': dict(Kd=(1, 1, 1), metallic=1.0, smoothness=0.85, note='coin faces; add GoldCoin_Normal.png'),
    'GiftBag': dict(Kd=(1, 1, 1), metallic=0.0, smoothness=0.25, note='matte black paper with gold foil print'),
    'TerminalTop': dict(Kd=(1, 1, 1), metallic=0.0, smoothness=0.7, emission=0.25, note='keypad + screen print; optional emission with the same texture'),
    'PosScreen': dict(Kd=(1, 1, 1), metallic=0.0, smoothness=0.9, emission=0.6, note='till screen; use as emission map for a lit screen'),
    'GemPaper': dict(Kd=(1, 1, 1), metallic=0.0, smoothness=0.2, note='diamond paper: left half outside print, right half blue liner'),
}
MATS.update({'PaperBlack': dict(Kd=(0.03, 0.03, 0.032), metallic=0.0, smoothness=0.3, note='matte black card box')})
ALL = dict(MATS); ALL.update(TEXMAT)

def mtl_for(name):
    if name in TEXMAT:
        d = TEXMAT[name]
        return dict(Kd=(1, 1, 1), Ks=(0.3, 0.3, 0.3) if d['metallic'] < 0.5 else (0.6, 0.6, 0.6), Ns=round(10 + 990 * d['smoothness'] ** 2, 1), d=1.0, map_Kd=TEX[name])
    return mtl(name)

manifest = {}
def emit(name, parts, do_ground=True, offset=None, note=''):
    if do_ground:
        lo, hi = bbox(parts)
        off = np.array([(lo[0] + hi[0]) / 2, lo[1], (lo[2] + hi[2]) / 2])
    else:
        off = np.zeros(3) if offset is None else np.asarray(offset)
    parts = [p.xf(t=-off) for p in parts]
    mats = {p.mat: mtl_for(p.mat) for p in parts}
    tris = write_obj(os.path.join(OUT, name + '.obj'), parts, mats, HEADER)
    lo, hi = bbox(parts)
    manifest[name] = dict(tris=int(tris), size_m=[round(float(x), 4) for x in hi - lo], min=[round(float(x), 4) for x in lo],
                          max=[round(float(x), 4) for x in hi], materials=sorted(mats), offset=[round(float(x), 5) for x in off], note=note,
                          textures=sorted({TEX[m] for m in mats if m in TEX}))
    print('%-28s %6d tris  %s' % (name, tris, ' x '.join('%.1f' % (v * 1000) for v in hi - lo)))
    return off

# ---------------------------------------------------------------- rings (finger axis X, stone up)
emit('RingSolitaireDiamond', R.ring_solitaire())
emit('RingGoldBand', R.ring_band())
emit('RingSapphireHalo', R.ring_halo())
emit('RingDiamondEternity', R.ring_eternity())
emit('RingRubyThreeStone', R.ring_three_stone())
# ---------------------------------------------------------------- earrings
emit('EarringsDiamondStuds', I.earrings_studs())
emit('EarringsGoldHoops', I.earrings_hoops())
# ---------------------------------------------------------------- bust + necklaces (draped ones share the bust frame)
bust_off = emit('NecklaceBust', I.bust())
emit('NecklacePearlDraped', N.pearl_draped(), do_ground=False, offset=bust_off, note='same transform as NecklaceBust')
emit('NecklacePendantDraped', N.pendant_draped(), do_ground=False, offset=bust_off, note='same transform as NecklaceBust')
emit('NecklacePearlDropped', N.pearl_dropped())
emit('NecklacePendantDropped', N.pendant_dropped())
# ---------------------------------------------------------------- bracelets
emit('BraceletTennisDiamond', I.tennis_bracelet())
emit('BangleGold', I.bangle())
# ---------------------------------------------------------------- watch + pillow
pil_off = emit('WatchPillow', I.watch_pillow())
emit('WatchDressSteel', I.watch(), do_ground=False, offset=pil_off, note='same transform as WatchPillow (strap wraps the pillow)')
# ---------------------------------------------------------------- loose gems (girdle centred, culet at y = 0)
emit('GemRoundBrilliant', [G.round_brilliant(6.5 * MM, 'Diamond')])
emit('GemPrincessCut', [G.princess_cut(5.5 * MM, 'Diamond')])
emit('GemEmeraldCut', [G.emerald_cut(9.0 * MM, 7.0 * MM, 'Emerald')])
emit('GemOvalSapphire', [G.oval_brilliant(8.0 * MM, 6.0 * MM, 'Sapphire')])
emit('GemCushionRuby', [G.cushion_brilliant(6.5 * MM, 'Ruby')])
emit('GemPearDiamond', [G.pear_brilliant(9.0 * MM, 6.0 * MM, 'Diamond')])
emit('GemParcel', I.gem_parcel())
# ---------------------------------------------------------------- displays
emit('RingCone', I.ring_cone())
emit('EarringStand', I.earring_stand())
emit('RingBoxOpen', I.ring_box(105))
emit('RingBoxClosed', I.ring_box(0))
for k, cell in enumerate((0, 1, 6, 3)):
    emit('PriceTag%02d' % (k + 1), I.price_tag(cell), note='atlas cell %d' % cell)
for k, cell in enumerate((2, 4, 5, 7)):
    emit('PriceStand%02d' % (k + 1), I.price_stand(cell), note='atlas cell %d' % cell)
# ---------------------------------------------------------------- packaging, bullion, counter
emit('GiftBag', I.gift_bag())
emit('GiftBox', I.gift_box())
emit('GoldBar1kg', I.gold_bar_cast())
emit('GoldBar100g', I.gold_bar_minted())
emit('GoldCoin', I.gold_coin())
emit('JewelersLoupe', I.loupe())
emit('PaymentTerminal', I.payment_terminal())
emit('PosTablet', I.pos_tablet())

json.dump(dict(models=manifest, materials={k: v for k, v in ALL.items()}), open(os.path.join(OUT, 'build_manifest.json'), 'w'), indent=1)
